// The starter set below contains a scenario MCQ, multi-select and open scenario
// per competency; the extended catalogue below brings every competency to 15
// standard questions (105 total) plus the 10 spoken customer-advisory items
// (115 published overall), including scale items for self-assessment.
const O = (id, label) => ({ id, label });
const optionSet = (labels) => labels.map((label, i) => O(String.fromCharCode(97 + i), label));
const singleQ = (competency, order, prompt, labels, correct, difficulty = 'intermediate') => ({
  competency, type: 'mcq_single', points: 4, difficulty, order, prompt,
  options: optionSet(labels), correct_option_ids: [correct],
});
const multiQ = (competency, order, prompt, labels, correct, difficulty = 'intermediate') => ({
  competency, type: 'mcq_multi', points: 4, difficulty, order, prompt,
  options: optionSet(labels), correct_option_ids: correct,
});
const scaleQ = (competency, order, prompt, difficulty = 'foundation') => ({
  competency, type: 'scale', points: 3, difficulty, order, prompt,
  options: [], correct_option_ids: [],
});
const textQ = (competency, order, prompt, rubric) => ({
  competency, type: 'text', points: 6, difficulty: 'advanced', order, prompt,
  options: [], correct_option_ids: [], rubric,
});

